import jsPDFModule from 'jspdf';
const jsPDF = jsPDFModule.jsPDF || jsPDFModule;
export function createCisoAuditPdfReport(data) {
    const doc = new jsPDF();
    const title = data.title || 'CYBERMIND SOC PLATFORM - SECURITY AUDIT REPORT';
    const classification = data.classification || 'CONFIDENTIAL / CISO AUDIT';
    const riskScore = data.riskScore ?? 92;
    doc.setFontSize(16);
    doc.text(title, 14, 20);
    doc.setFontSize(10);
    doc.text(`Generated: ${new Date().toLocaleString()}`, 14, 28);
    doc.text(`Classification: ${classification}`, 14, 34);
    doc.text(`Overall Security Risk Score: ${riskScore} / 100`, 14, 40);
    doc.setFontSize(12);
    doc.text('1. Executive Telemetry Summary', 14, 52);
    doc.setFontSize(9);
    const summaryText = data.summary || 'Defensive security sensors completed telemetry audit across enterprise assets. All telemetry feeds indicate stable posture within baseline operational metrics.';
    const splitSummary = doc.splitTextToSize(summaryText, 180);
    doc.text(splitSummary, 14, 58);
    doc.setFontSize(12);
    doc.text('2. MITRE ATT&CK Framework Detections Mapped', 14, 85);
    doc.setFontSize(9);
    doc.text('- T1110.001 (Brute Force): Perimeter password guessing attempt blocked', 14, 93);
    doc.text('- T1059.001 (PowerShell): Encoded script execution policy enforced', 14, 99);
    doc.text('- T1070.001 (Indicator Removal): System Event log clearing monitored', 14, 105);
    doc.setFontSize(12);
    doc.text('3. Defensive Remediation Guidance', 14, 120);
    doc.setFontSize(9);
    doc.text('1. Maintain strict IP whitelist filters on management services.', 14, 128);
    doc.text('2. Enforce 2FA on remote management consoles.', 14, 134);
    doc.text('3. Continuously correlate software versions against NVD CVE feeds.', 14, 140);
    const arrayBuffer = doc.output('arraybuffer');
    return Buffer.from(arrayBuffer);
}
